type Point = { x: number; y: number };

function distanceFromOrigin(p: Point): number {
  return Math.sqrt(p.x * p.x + p.y * p.y);
}

const marker = { x: 3, y: 4, label: 'home' }; // extra field is fine
console.log(distanceFromOrigin(marker));

// TODO: add type annotations so a and b are numbers and it returns a number
function add(a, b) {
  return a + b;
}

console.log(add(2, 3));

solution.code:
function add(a: number, b: number): number {
  return a + b;
}

console.log(add(2, 3));

brokenCode.code:
const user = { name: 'Grace', age: 36 };

function welcome(u) {
  return 'Welcome, ' + u.naem; // typo: naem
}

console.log(welcome(user));

solution.code:
type User = { name: string; age: number };

function welcome(u: User): string {
  return 'Welcome, ' + u.name; // typo fixed; TS would have flagged 'naem'
}

console.log(welcome({ name: 'Grace', age: 36 }));

function fullName(first: string, last: string): string {
  return first + ' ' + last;
}

console.log(fullName('Ada', 'Lovelace'));

alternativeApproaches.code:
function fullName(first: string, last: string) {
  return first + ' ' + last; // return type inferred as string
}
